fn fixture_xy() -> (Matrix, Vec<f64>) {
    let rows: Vec<Vec<f64>> = X.chunks_exact(3).map(|c| c.to_vec()).collect();
    (Matrix::new(rows).unwrap(), Y.to_vec())
}

fn approx(a: f64, b: f64, tol: f64) -> bool {
    (a - b).abs() < tol
}

/// GridSearchCV(Ridge, alpha=[1.0, 0.1, 1.0], cv=KFold(3), scoring=r2).
///
/// The duplicated alpha exercises tie handling: both `1.0` candidates must
/// share rank 2 and the middle candidate must win outright.
#[test]
fn grid_search_matches_sklearn_scores_ranks_and_tie_breaks() {
    let (x, y) = fixture_xy();
    let grid: ParamGrid = vec![(
        "alpha",
        vec![
            ParamValue::Float(1.0),
            ParamValue::Float(0.1),
            ParamValue::Float(1.0),
        ],
    )];
    let mut gs =
        GridSearchCV::new(Ridge::new(), grid, r2_score).with_cv(KFold::new().with_n_splits(3));
    gs.fit(&x, &y).unwrap();

    let results = gs.cv_results().unwrap();
    let means = [0.9286609026885503, 0.9987601593828295, 0.9286609026885503];
    let stds = [
        0.07643130349385702,
        0.0014267335007012744,
        0.07643130349385702,
    ];
    // sklearn's `split{f}_test_score[i]` transposed to datarust's
    // candidate-major `split_scores[i][f]`.
    let folds = [
        [0.8216859822040204, 0.9955607087790073, 0.968736017082623],
        [0.9967530592160592, 0.9999426351866914, 0.9995847837457377],
        [0.8216859822040204, 0.9955607087790073, 0.968736017082623],
    ];

    for (i, expected) in means.iter().enumerate() {
        assert!(
            approx(results.mean_test_score[i], *expected, 1e-8),
            "mean[{i}] {} vs {expected}",
            results.mean_test_score[i]
        );
    }
    for (i, expected) in stds.iter().enumerate() {
        assert!(
            approx(results.std_test_score[i], *expected, 1e-8),
            "std[{i}] {} vs {expected}",
            results.std_test_score[i]
        );
    }
    for (i, expected) in folds.iter().enumerate() {
        for (f, expected_score) in expected.iter().enumerate() {
            assert!(
                approx(results.split_scores[i][f], *expected_score, 1e-8),
                "split[{i}][{f}] {} vs {expected_score}",
                results.split_scores[i][f]
            );
        }
    }

    assert_eq!(results.rank_test_score, vec![2, 1, 2]);
    assert_eq!(gs.best_index(), Some(1));
    match gs.best_params().unwrap() {
        [("alpha", ParamValue::Float(a))] => assert_eq!(*a, 0.1),
        other => panic!("unexpected best params {other:?}"),
    }
}

/// A grid whose candidates are all identical must select index 0, like
/// sklearn's first-occurrence `best_index_`.
#[test]
fn grid_search_all_ties_select_first_candidate() {
    let (x, y) = fixture_xy();
    let grid: ParamGrid = vec![(
        "alpha",
        vec![ParamValue::Float(1.0), ParamValue::Float(1.0)],
    )];
    let mut gs =
        GridSearchCV::new(Ridge::new(), grid, r2_score).with_cv(KFold::new().with_n_splits(3));
    gs.fit(&x, &y).unwrap();
    assert_eq!(gs.best_index(), Some(0));
}

/// validation_curve(Ridge, alpha=[0.1, 1, 10], cv=KFold(3), scoring=r2):
/// flattened `[param][fold]` fixture values.
#[test]
fn validation_curve_matches_sklearn_values() {
    let (x, y) = fixture_xy();
    let (train, test) = validation_curve(
        &Ridge::new(),
        &x,
        &y,
        "alpha",
        &[
            ParamValue::Float(0.1),
            ParamValue::Float(1.0),
            ParamValue::Float(10.0),
        ],
        &KFold::new().with_n_splits(3),
        r2_score,
    )
    .unwrap();

    let vc_train = [
        0.9999137811191174,
        0.9999451658706356,
        0.9997363189468305,
        0.9945116588434062,
        0.9955209172978263,
        0.980327442557852,
        0.8551861061775953,
        0.8440541916141386,
        0.6198905514474029,
    ];
    let vc_test = [
        0.9967530592160592,
        0.9999426351866914,
        0.9995847837457377,
        0.8216859822040204,
        0.9955607087790073,
        0.968736017082623,
        -1.3616286043825463,
        0.8475610969520407,
        0.3810568239774298,
    ];

    for (i, expected) in vc_train.iter().enumerate() {
        let (p, f) = (i / 3, i % 3);
        assert!(
            approx(train[p][f], *expected, 1e-8),
            "train[{p}][{f}] {} vs {expected}",
            train[p][f]
        );
    }
    for (i, expected) in vc_test.iter().enumerate() {
        let (p, f) = (i / 3, i % 3);
        assert!(
            approx(test[p][f], *expected, 1e-8),
            "test[{p}][{f}] {} vs {expected}",
            test[p][f]
        );
    }
}

