/// The refit behavior: `best_estimator_` must reproduce sklearn's refit-on-
/// full-data predictions (same alpha winner).
#[test]
fn grid_search_refit_predicts_like_sklearn_best() {
    let (x, y) = fixture_xy();
    let grid: ParamGrid = vec![(
        "alpha",
        vec![
            ParamValue::Float(1.0),
            ParamValue::Float(0.1),
            ParamValue::Float(1.0),
        ],
    )];
    let mut gs =
        GridSearchCV::new(Ridge::new(), grid, r2_score).with_cv(KFold::new().with_n_splits(3));
    gs.fit(&x, &y).unwrap();

    // Reference: sklearn Ridge(alpha=0.1).fit(X, y).predict(X[:2]).
    let expected = [6.831418935732922, 4.597978005127771];
    let best = gs.best_estimator().unwrap();
    let preds = best.predict(&x).unwrap();
    for (got, expected) in preds.iter().zip(expected.iter()) {
        assert!(approx(*got, *expected, 1e-6), "got {got} vs {expected}");
    }
}
